recipes.code:
{
  "inputs": [
    {
      "id": "voyagier-token",
      "type": "promptString",
      "description": "Voyagier Personal Access Token (travel.voyagier.com → Settings → Personal Access Tokens). Access is by invitation — request at https://www.voyagier.com/agents.",
      "password": true
    }
  ],
  "servers": {
    "cli": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@voyagier/cli@2.14.0",
        "mcp"
      ],
      "env": {
        "VOYAGIER_TOKEN": "${input:voyagier-token}",
        "VOYAGIER_API_URL": "<voyagier-api-url>"
      }
    }
  }
}
